//
// Prepare an embedded module, generated by the cuda tapir target for (eventual)
// code generation.
//
//===----------------------------------------------------------------------===//

#include "EmbPrepareImpl.h"
// #include "kitsune/Core/AddrSpaceUtils.h"
#include "kitsune/Core/KitsuneTTOptions.h"
#include "llvm/ADT/StringExtras.h"
#include "llvm/IR/Attributes.h"
#include "llvm/IR/Function.h"
#include "llvm/IR/Module.h"

using namespace llvm;

namespace {

class EmbPrepareCuda {
private:
  const KitsuneTTOptions &tto;
  const detail::EmbPrepareOptions &prepOpts;

private:
  /// Fix the attributes on the "non-kernel" functions. The attributes on the
  /// kernel function will have been set by the tapir targets.
  bool fixDeviceFuncAttrs(Module &devM) {
    bool changed = false;
    for (Function &f : devM.functions()) {
      // if (f.hasFnAttribute(Attribute::KitDevice)) {
        f.removeFnAttr("target-cpu");
        f.removeFnAttr("target-features");
        f.removeFnAttr("tune-cpu");

        f.addFnAttr("target-cpu", tto.getCudaArch());
        f.addFnAttr(
            "target-features",
            join_items(",", tto.getCudaTargetFeatures(), tto.getCudaArch()));

        bool hasNoInline = f.hasFnAttribute(Attribute::NoInline);
        if (prepOpts.inlineAllForce) {
          f.removeFnAttr(Attribute::NoInline);
          f.addFnAttr(Attribute::AlwaysInline);
        } else if (prepOpts.inlineAll and (not hasNoInline)) {
          f.addFnAttr(Attribute::AlwaysInline);
        }

        changed |= true;
      // }
    }
    return changed;
  }

public:
  EmbPrepareCuda(const KitsuneTTOptions &tto,
                 const detail::EmbPrepareOptions &prepOpts)
      : tto(tto), prepOpts(prepOpts) {}

  bool run(Module &devM) {
    bool changed = false;

    changed |= fixDeviceFuncAttrs(devM);
    // changed |= stripKitsuneAddrSpaces(devM);

    return changed;
  }
};

} // namespace

bool llvm::detail::embPrepareCuda(Module &m, const KitsuneTTOptions &tto,
                                  const detail::EmbPrepareOptions &prepOpts) {
  return EmbPrepareCuda(tto, prepOpts).run(m);
}
